// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // keep the input admissible: initialize must not revert
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after a successful initialize, the stored base token
        // is exactly the one supplied by the caller.
        assertTrue(c.baseToken() == baseToken);
    }
}
